type Product = { id:string; name:string; slug:string; brand:string|null; category_id:string|null; price:number; old_price:number|null; cost_price:number; sku:string|null; supplier:string|null; promo_price:number|null; promo_label:string|null; promo_starts_at:string|null; promo_ends_at:string|null; image_url:string|null; short_description:string|null; description:string|null; highlights:string[]; in_stock:boolean; featured:boolean; stock_quantity:number; low_stock_threshold:number; visible:boolean; sort_order:number };
type Category = { id:string; slug:string; name:string; description:string|null; image_url:string|null; sort_order:number; parent_id:string|null; visible:boolean };
type Repair = { id:string; device_brand:string; device_model:string; service_name:string; estimated_price:number; repair_time:string|null; available:boolean; slug:string|null; name:string|null; description:string|null; price_from:number|null; duration:string|null; active:boolean|null; sort_order:number|null };
type ScreenPrice = { id:string; brand:string; model:string; available:boolean; screen_price:number; installation_price:number; notes:string|null; active:boolean; updated_at:string };
type OrderItem = { id?:string; name?:string; quantity?:number; price?:number; image_url?:string|null }; type Order = { id:string; reference:string; customer_name:string; email?:string|null; phone:string; address?:string|null; city?:string|null; items:OrderItem[]; total:number; status:string; created_at:string; notes:string|null }; type StockMovement = { id:string; product_id:string; quantity:number; movement_type:string; reason:string|null; previous_quantity:number; new_quantity:number; created_at:string; product_name?:string }; type Promotion = { id:string; name:string; description:string|null; discount_type:"percent"|"fixed"; discount_value:number; scope_type:"all"|"category"|"product"; scope_id:string|null; starts_at:string|null; ends_at:string|null; active:boolean; };
type Settings = { id:string; store_name:string; whatsapp:string; phone:string; address:string; hours:string; banner:string|null };

const emptyProduct: Omit<Product,"id"> = { name:"",slug:"",brand:"",category_id:null,price:0,old_price:null,cost_price:0,sku:"",supplier:"",promo_price:null,promo_label:"",promo_starts_at:null,promo_ends_at:null,image_url:"",short_description:"",description:"",highlights:[],in_stock:true,featured:false,stock_quantity:0,low_stock_threshold:2,visible:true,sort_order:0 };
const emptyRepair: Omit<Repair,"id"> = { device_brand:"Tous",device_model:"Tous",service_name:"",estimated_price:0,repair_time:"",available:true,slug:"",name:"",description:"",price_from:0,duration:"",active:true,sort_order:0 };
const emptyCategory: Omit<Category,"id"> = { name:"",slug:"",description:"",image_url:"",sort_order:0,parent_id:null,visible:true };

function AdminPage() {
  const [token,setToken]=useState<string|null>(null);
  const [email,setEmail]=useState(""); const [password,setPassword]=useState(""); const [error,setError]=useState(""); const [loading,setLoading]=useState(false);
  const [tab,setTab]=useState("dashboard"); const [sidebarOpen,setSidebarOpen]=useState(true);
  const [customers,setCustomers]=useState<Array<{id:string;email:string|null;created_at:string;last_sign_in_at:string|null;full_name:string|null;phone:string|null;city:string|null;order_count:number;total_spent:number;last_order_at:string|null}>>([]);
  const [customerSearch,setCustomerSearch]=useState("");
  const [dashboardPeriod,setDashboardPeriod]=useState<"all"|"today"|"7d"|"30d">("all");
  const [productCategoryFilter,setProductCategoryFilter]=useState("all");
  const [productSearch,setProductSearch]=useState("");
  const [productStockFilter,setProductStockFilter]=useState("all");
  const [productSort,setProductSort]=useState("newest");
  const [orderSearch,setOrderSearch]=useState("");
  const [orderStatusFilter,setOrderStatusFilter]=useState("all");
  const [products,setProducts]=useState<Product[]>([]); const [categories,setCategories]=useState<Category[]>([]); const [repairs,setRepairs]=useState<Repair[]>([]); const [orders,setOrders]=useState<Order[]>([]);
  const [settings,setSettings]=useState<Settings|null>(null); const [editing,setEditing]=useState<Omit<Product,"id"> & {id?:string}>(emptyProduct);
  const productFormRef=useRef<HTMLDivElement>(null); const [productEditRequest,setProductEditRequest]=useState(0);
  const categoryFormRef=useRef<HTMLDivElement>(null); const [categoryEditRequest,setCategoryEditRequest]=useState(0);
  const [editingRepair,setEditingRepair]=useState<Omit<Repair,"id"> & {id?:string}>(emptyRepair);
  const [editingCategory,setEditingCategory]=useState<Omit<Category,"id"> & {id?:string}>(emptyCategory);
  const [message,setMessage]=useState(""); const [selectedProducts,setSelectedProducts]=useState<string[]>([]); const [productBulkBusy,setProductBulkBusy]=useState(false);
  const [mfaReady,setMfaReady]=useState<boolean|null>(null); const [mfaEnrollment,setMfaEnrollment]=useState<{id:string;qr_code:string;secret:string}|null>(null); const [mfaFactorId,setMfaFactorId]=useState<string|null>(null); const [mfaChallengeId,setMfaChallengeId]=useState<string|null>(null); const [mfaCode,setMfaCode]=useState(""); const [mfaBusy,setMfaBusy]=useState(false);
  const [stockProductId,setStockProductId]=useState(""); const [stockMovementType,setStockMovementType]=useState("in"); const [stockQuantity,setStockQuantity]=useState(1); const [stockReason,setStockReason]=useState(""); const [stockMovements,setStockMovements]=useState<StockMovement[]>([]);
  const [promotions,setPromotions]=useState<Promotion[]>([]); const [editingPromotion,setEditingPromotion]=useState<Promotion>({id:"",name:"",description:null,discount_type:"percent",discount_value:0,scope_type:"all",scope_id:null,starts_at:null,ends_at:null,active:true});
  const [screenPrices,setScreenPrices]=useState<ScreenPrice[]>([]); const [screenSearch,setScreenSearch]=useState("");

  useEffect(()=>{if(tab==="products"&&productEditRequest>0){productFormRef.current?.scrollIntoView({behavior:"smooth",block:"start"});}},[productEditRequest,tab]);
  useEffect(()=>{if(tab==="categories"&&categoryEditRequest>0){categoryFormRef.current?.scrollIntoView({behavior:"smooth",block:"start"});}},[categoryEditRequest,tab]);

  const loadCustomers=async()=>{try{const rows=await supabaseRest<Array<{id:string;email:string|null;created_at:string;last_sign_in_at:string|null;full_name:string|null;phone:string|null;city:string|null;order_count:number;total_spent:number;last_order_at:string|null}>>("rpc/admin_list_customers",{method:"POST",body:{}});setCustomers(rows||[]);}catch(e){console.error("OROTRONIX: clients",e);}};

  const load=async()=>{ setLoading(true); setError(""); try {
    const [p,c,r,o,s,prom,sm,sp]=await Promise.all([
      supabaseRest<Product[]>("products",{query:"?select=*&order=sort_order.asc,created_at.desc"}),
      supabaseRest<Category[]>("categories",{query:"?select=*&order=sort_order.asc"}),
      supabaseRest<Repair[]>("repair_services",{query:"?select=*&order=sort_order.asc"}),
      supabaseRest<Order[]>("orders",{query:"?select=id,reference,customer_name,email,phone,address,city,items,total,status,created_at,notes&order=created_at.desc&limit=50"}),
      supabaseRest<Settings[]>("store_settings",{query:"?select=*&limit=1"}),
      supabaseRest<Promotion[]>("promotions",{query:"?select=*&order=created_at.desc"}),
      supabaseRest<StockMovement[]>("stock_movements",{query:"?select=*&order=created_at.desc&limit=100"}),
      supabaseRest<ScreenPrice[]>("repair_screen_prices",{query:"?select=*&order=brand.asc,model.asc"})
    ]);
    setProducts(p); setCategories(c); setRepairs(r); setOrders(o); setSettings(s[0] ?? null); setPromotions(prom || []); setStockMovements(sm || []); setScreenPrices(sp || []); await loadCustomers();
  } catch(e){setError(e instanceof Error?e.message:"Erreur de chargement");} finally{setLoading(false);} };

  const verifyAdmin=async()=>{ const ok=await supabaseRest<boolean>("rpc/is_admin_identity",{method:"POST",body:{}}); if(!ok) throw new Error("Accès administrateur refusé."); return true; };
  const adminBooted=useRef(false);
  useEffect(()=>{
    if(typeof window==="undefined" || adminBooted.current) return;
    adminBooted.current=true;
    const hash=new URLSearchParams(window.location.hash.replace(/^#/,""));
    const oauthToken=hash.get("access_token");
    const oauthRefresh=hash.get("refresh_token");
    if(oauthToken){
      window.history.replaceState({},document.title,window.location.pathname+window.location.search);
      setSupabaseAccessToken(oauthToken);
      sessionStorage.setItem("orotronix_admin_token",oauthToken);
      if(oauthRefresh) sessionStorage.setItem("orotronix_admin_refresh_token",oauthRefresh);
      setToken(oauthToken);
      return;
    }
    const savedToken=sessionStorage.getItem("orotronix_admin_token");
    if(savedToken){
      setSupabaseAccessToken(savedToken);
      setToken(savedToken);
      return;
    }
    void refreshSupabaseAdminSession().then((restored)=>{
      if(restored){
        setToken(restored);
      }else{
        setSupabaseAccessToken(null);
        setToken(null);
      }
    });
  },[]);
  useEffect(()=>{if(!token)return;setSupabaseAccessToken(token);setMfaReady(null);setError("");void verifyAdmin().then(()=>prepareAdminMfa()).then((ready)=>{if(ready)void load();}).catch((e)=>{setMfaReady(null);setError(e instanceof Error?e.message:"La vérification administrateur a échoué.");});},[token]);
  const login=async(e:React.FormEvent)=>{e.preventDefault();setError("");try{const d=await supabaseAuth("token?grant_type=password",{email,password});setSupabaseAccessToken(d.access_token);await verifyAdmin();sessionStorage.setItem("orotronix_admin_token",d.access_token);if(d.refresh_token)sessionStorage.setItem("orotronix_admin_refresh_token",d.refresh_token);setToken(d.access_token);}catch(e){setError(e instanceof Error?e.message:"Connexion impossible");}};
  const prepareAdminMfa=async():Promise<boolean>=>{ if(!token)return false; setMfaBusy(true); setError(""); try { if(getJwtAal(token)==="aal2"){sessionStorage.removeItem("orotronix_admin_mfa_enrollment");setMfaReady(true);return true;} const factors=await listAdminMfaFactors(token); const verified=(factors.all||[]).find(f=>f.status==="verified"); if(verified){ const challenge=await challengeAdminTotp(token,verified.id); setMfaFactorId(verified.id); setMfaChallengeId(challenge.id); setMfaEnrollment(null); setMfaReady(false); return false; } const pending=(factors.all||[]).find(f=>f.status==="unverified"); if(pending){ const savedRaw=sessionStorage.getItem("orotronix_admin_mfa_enrollment"); if(savedRaw){ try { const saved=JSON.parse(savedRaw) as {id:string;qr_code:string;secret:string}; if(saved.id===pending.id){setMfaFactorId(saved.id);setMfaChallengeId(null);setMfaEnrollment(saved);setMfaReady(false);return false;} } catch {} } throw new Error("Une configuration MFA est déjà en attente. Utilisez la même fenêtre où le QR code a été affiché, puis saisissez le code."); } const enrollment=await enrollAdminTotp(token); const pendingEnrollment={id:enrollment.id,qr_code:enrollment.totp.qr_code,secret:enrollment.totp.secret}; sessionStorage.setItem("orotronix_admin_mfa_enrollment",JSON.stringify(pendingEnrollment)); setMfaEnrollment(pendingEnrollment); setMfaFactorId(enrollment.id); setMfaChallengeId(null); setMfaReady(false); return false; } catch(e){setMfaReady(null);setError(e instanceof Error?e.message:"Impossible de préparer la MFA."); return false; } finally{setMfaBusy(false);} };
  const confirmAdminMfa=async()=>{ if(!token||!mfaFactorId||!mfaCode)return; setMfaBusy(true); setError(""); try { const challengeId=mfaChallengeId || (await challengeAdminTotp(token,mfaFactorId)).id; const result=await verifyAdminTotp(token,mfaFactorId,challengeId,mfaCode); if(result.access_token){setSupabaseAccessToken(result.access_token);sessionStorage.setItem("orotronix_admin_token",result.access_token);if(result.refresh_token)sessionStorage.setItem("orotronix_admin_refresh_token",result.refresh_token);setToken(result.access_token);} setMfaEnrollment(null);setMfaFactorId(null);setMfaChallengeId(null);setMfaCode("");setMfaReady(true);setMessage("Authentification à deux facteurs validée."); void load(); } catch(e){setError(e instanceof Error?e.message:"Code MFA invalide ou expiré.");} finally{setMfaBusy(false);} };
  const loginGoogle=()=>{setError("");if(!supabaseConfigured){setError("Supabase n’est pas configuré.");return;}const base=(import.meta.env.VITE_SUPABASE_URL || "https://qeqqfelebzxwupsqyzbz.supabase.co").replace(/\/$/,"");const key=import.meta.env.VITE_SUPABASE_ANON_KEY || "sb_publishable_nnvN9OsnpO_ipsFx0l-orw_yERvs7da";if(!base||!key){setError("Supabase n’est pas configuré.");return;}const redirectTo=window.location.origin+"/admin";const authUrl=base+"/auth/v1/authorize?provider=google&redirect_to="+encodeURIComponent(redirectTo)+"&prompt="+encodeURIComponent("select_account");window.location.assign(authUrl);};
  // Admin MFA: keep the verified AAL2 session isolated from customer auth state.
  const logout=async()=>{const currentToken=sessionStorage.getItem("orotronix_admin_token");if(currentToken)await supabaseSignOut(currentToken,"local");sessionStorage.removeItem("orotronix_admin_token");sessionStorage.removeItem("orotronix_admin_refresh_token");sessionStorage.removeItem("orotronix_admin_mfa_enrollment");setSupabaseAccessToken(null);setToken(null);setMfaReady(null);};
  useEffect(()=>{if(!token)return;const timer=window.setInterval(()=>void load(),60000);return()=>window.clearInterval(timer);},[token]);

  const dashboardOrders=orders.filter(o=>{if(dashboardPeriod==="all")return true;const days=dashboardPeriod==="today"?1:dashboardPeriod==="7d"?7:30;return Date.now()-new Date(o.created_at).getTime()<days*86400000;});

  if(!supabaseConfigured)return <Shell><Panel><h1 className="font-display text-2xl font-semibold">Administration OROTRONIX</h1><p className="mt-3 text-sm text-muted-foreground">Ajoutez VITE_SUPABASE_URL et VITE_SUPABASE_ANON_KEY dans Cloudflare Pages.</p><Link className="mt-6 inline-block text-sm text-gold" to="/">← Retour au site</Link></Panel></Shell>;
  if(!token)return <Shell><form onSubmit={login} className="mx-auto w-full max-w-md rounded-2xl border border-gold/20 bg-card p-7 shadow-2xl shadow-black/20"><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-lg border border-gold/30 bg-gold/5 text-gold"><LockKeyhole className="h-5 w-5"/></div><div><p className="text-xs uppercase tracking-[0.22em] text-gold">OROTRONIX</p><p className="text-xs text-muted-foreground">Administration sécurisée</p></div></div><h1 className="mt-7 font-display text-2xl font-semibold">Espace administration</h1><p className="mt-2 text-sm text-muted-foreground">Accès réservé aux comptes administrateurs autorisés.</p><div className="mt-6 space-y-4"><div><Label>Email</Label><Input className="mt-2 bg-surface" type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username" required/></div><div><Label>Mot de passe</Label><Input className="mt-2 bg-surface" type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></div></div>{error&&<p role="alert" className="mt-4 rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</p>}<Button className="mt-6 w-full" type="submit" disabled={loading}>{loading?"Connexion…":"Se connecter"}</Button><div className="my-5 flex items-center gap-3"><span className="h-px flex-1 bg-border"/><span className="text-[11px] uppercase tracking-widest text-muted-foreground">ou</span><span className="h-px flex-1 bg-border"/></div><Button type="button" variant="outline" className="h-11 w-full border-border bg-background/40" onClick={loginGoogle}>Continuer avec Google</Button><Link className="mt-5 block text-center text-xs text-muted-foreground hover:text-gold" to="/">← Retour au site</Link></form></Shell>;

  if(token && mfaReady===null) return <Shell><Panel><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-lg border border-gold/30 bg-gold/5 text-gold"><LockKeyhole className="h-5 w-5"/></div><div><p className="text-xs uppercase tracking-[0.22em] text-gold">OROTRONIX</p><p className="text-xs text-muted-foreground">Vérification administrateur</p></div></div><h1 className="mt-7 font-display text-2xl font-semibold">Vérification de sécurité</h1><p className="mt-2 text-sm text-muted-foreground">Vérification de vos droits administrateur et de la double authentification…</p>{error&&<><p role="alert" className="mt-5 rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</p><Button className="mt-4 w-full" onClick={()=>{setError("");setMfaReady(null);void prepareAdminMfa();}} disabled={mfaBusy}>{mfaBusy?"Vérification…":"Réessayer"}</Button></>}</Panel></Shell>;

  if(token && mfaReady===false) return <Shell><Panel><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-lg border border-gold/30 bg-gold/5 text-gold"><LockKeyhole className="h-5 w-5"/></div><div><p className="text-xs uppercase tracking-[0.22em] text-gold">OROTRONIX</p><p className="text-xs text-muted-foreground">Sécurité administrateur</p></div></div><h1 className="mt-7 font-display text-2xl font-semibold">{mfaEnrollment?"Activer la double authentification":"Vérification en deux étapes"}</h1><p className="mt-2 text-sm text-muted-foreground">{mfaEnrollment?"Scannez le QR avec Google Authenticator, Microsoft Authenticator ou une application TOTP compatible.":"Ouvrez votre application Authenticator et saisissez le code à 6 chiffres affiché."}</p>{mfaEnrollment&&<><div className="mt-6 flex justify-center rounded-xl border border-border bg-white p-4"><img src={mfaEnrollment.qr_code} alt="QR code de configuration MFA" className="h-56 w-56"/></div><div className="mt-4 rounded-xl border border-border bg-surface p-4"><p className="text-xs text-muted-foreground">Clé de secours</p><p className="mt-1 break-all font-mono text-sm">{mfaEnrollment.secret}</p></div></>} {mfaFactorId&&<div className="mt-5"><Label>Code à 6 chiffres</Label><Input className="mt-2 bg-surface text-center text-lg tracking-[0.35em]" inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={mfaCode} onChange={e=>setMfaCode(e.target.value.replace(/\D/g,"").slice(0,6))}/></div>}<Button className="mt-5 w-full" onClick={confirmAdminMfa} disabled={mfaBusy||mfaCode.length!==6}>{mfaBusy?"Vérification…":mfaEnrollment?"Vérifier et activer":"Vérifier le code"}</Button>{error&&<p role="alert" className="mt-4 rounded-md border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</p>}<button type="button" className="mt-5 w-full text-xs text-muted-foreground hover:text-gold" onClick={logout}>Se déconnecter</button></Panel></Shell>;

  const saveProduct=async(e:React.FormEvent)=>{e.preventDefault();setError("");setMessage("");if(!editing.category_id){setError("Veuillez sélectionner une catégorie pour le produit.");return;}try{const stockQuantity=Math.max(0,Math.floor(Number(editing.stock_quantity)||0));const lowStockThreshold=Math.max(0,Math.floor(Number(editing.low_stock_threshold)||0));const body={...editing,price:Number(editing.price)||0,old_price:editing.old_price===null||editing.old_price===""?null:Number(editing.old_price),cost_price:Number(editing.cost_price)||0,promo_price:editing.promo_price===null||editing.promo_price===""?null:Number(editing.promo_price),highlights:Array.isArray(editing.highlights)?editing.highlights:[],stock_quantity:stockQuantity,low_stock_threshold:lowStockThreshold,in_stock:stockQuantity>0,sku:editing.sku?.trim()||null,supplier:editing.supplier?.trim()||null};if(editing.id){const previous=products.find(p=>p.id===editing.id);await supabaseRest("products",{method:"PATCH",query:"?id=eq."+editing.id,body,prefer:"return=minimal"});if(previous&&previous.stock_quantity!==stockQuantity){await supabaseRest("stock_movements",{method:"POST",body:{product_id:editing.id,quantity:stockQuantity-previous.stock_quantity,movement_type:"adjustment",reason:"Modification du stock depuis la fiche produit",previous_quantity:previous.stock_quantity,new_quantity:stockQuantity}});}}else{const created=await supabaseRest<Product[]>("products",{method:"POST",body,prefer:"return=representation"});const createdProduct=Array.isArray(created)?created[0]:null;if(createdProduct&&stockQuantity>0)await supabaseRest("stock_movements",{method:"POST",body:{product_id:createdProduct.id,quantity:stockQuantity,movement_type:"in",reason:"Stock initial du produit",previous_quantity:0,new_quantity:stockQuantity}});}setEditing(emptyProduct);setMessage("Produit enregistré.");await load();}catch(e){setError(e instanceof Error?e.message:"Erreur d’enregistrement");}};
  const quickStock=async(p:Product,delta:number)=>{setError("");try{const type=delta>=0?"in":"out";await supabaseRest("rpc/admin_stock_adjust",{method:"POST",body:{p_product_id:p.id,p_quantity:Math.abs(delta),p_movement_type:type,p_reason:"Ajustement rapide depuis Produits"}});setMessage(p.name+" · stock mis à jour");await load();}catch(e){setError(e instanceof Error?e.message:"Mise à jour du stock impossible");}};
  const duplicateProduct=async(p:Product)=>{setError("");setMessage("");try{const slugBase=p.slug+"-copy";const body={...p,id:undefined,slug:slugBase,name:p.name+" (copie)"};delete (body as {id?:string}).id;await supabaseRest("products",{method:"POST",body,prefer:"return=minimal"});setMessage("Produit dupliqué.");await load();}catch(e){setError(e instanceof Error?e.message:"Duplication impossible");}};
  const deleteProduct=async(id:string)=>{if(!confirm("Supprimer ce produit ?"))return;try{await supabaseRest("products",{method:"DELETE",query:"?id=eq."+id});setSelectedProducts(s=>s.filter(x=>x!==id));await load();}catch(e){setError(e instanceof Error?e.message:"Suppression impossible");}};
  const filteredProducts=products.filter(p=>(productCategoryFilter==="all"||p.category_id===productCategoryFilter)&&(productStockFilter==="all"||(productStockFilter==="in"?p.in_stock:!p.in_stock))&&p.name.toLowerCase().includes(productSearch.toLowerCase())).sort((a,b)=>productSort==="name"?a.name.localeCompare(b.name,"fr"):productSort==="price-low"?a.price-b.price:productSort==="price-high"?b.price-a.price:0);
  const toggleProduct=(id:string)=>setSelectedProducts(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);
  const toggleAllFiltered=()=>setSelectedProducts(s=>filteredProducts.every(p=>s.includes(p.id))?s.filter(id=>!filteredProducts.some(p=>p.id===id)):[...new Set([...s,...filteredProducts.map(p=>p.id)])]);
  const bulkProducts=async(action:"show"|"hide"|"stock0"|"stock1"|"featured"|"unfeatured")=>{if(!selectedProducts.length)return;setProductBulkBusy(true);setError("");try{const body=action==="show"?{visible:true}:action==="hide"?{visible:false}:action==="stock0"?{stock_quantity:0,in_stock:false}:action==="stock1"?{stock_quantity:1,in_stock:true}:action==="featured"?{featured:true}:{featured:false};for(const id of selectedProducts)await supabaseRest("products",{method:"PATCH",query:"?id=eq."+id,body,prefer:"return=minimal"});setSelectedProducts([]);setMessage("Action appliquée à "+selectedProducts.length+" produit(s).");await load();}catch(e){setError(e instanceof Error?e.message:"Action groupée impossible");}finally{setProductBulkBusy(false);}};
  const exportOrders=()=>{const headers=["Référence","Client","E-mail","Téléphone","Adresse","Ville","Total","Statut","Date","Notes"];const rows=orders.map(o=>[o.reference,o.customer_name,o.email||"",o.phone,o.address||"",o.city||"",String(o.total),o.status,new Date(o.created_at).toLocaleString("fr-MA"),o.notes||""]);const csv=[headers,...rows].map(row=>row.map(v=>"\""+String(v).replace(/\"/g,"\"\"")+"\"").join(";")).join("\n");const blob=new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="orotronix-commandes.csv";a.click();URL.revokeObjectURL(url);};
  const saveCategory=async(e:React.FormEvent)=>{e.preventDefault();setError("");try{const name=editingCategory.name.trim();if(!name)throw new Error("Le nom de la catégorie est obligatoire.");if(editingCategory.parent_id===editingCategory.id)throw new Error("Une catégorie ne peut pas être sa propre catégorie parente.");const slug=(editingCategory.slug.trim()||name.normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""));if(!slug)throw new Error("Le slug de la catégorie est obligatoire.");const body={...editingCategory,name,slug,description:editingCategory.description?.trim()||null,image_url:editingCategory.image_url?.trim()||null,sort_order:Math.max(0,Math.floor(Number(editingCategory.sort_order)||0)),parent_id:editingCategory.parent_id||null,visible:Boolean(editingCategory.visible)};if(editingCategory.id)await supabaseRest("categories",{method:"PATCH",query:"?id=eq."+editingCategory.id,body});else await supabaseRest("categories",{method:"POST",body});setEditingCategory(emptyCategory);setMessage("Catégorie enregistrée.");await load();}catch(e){setError(e instanceof Error?e.message:"Erreur");}};
  const deleteCategory=async(id:string)=>{const category=categories.find(c=>c.id===id);if(!category)return;if(categories.some(c=>c.parent_id===id)){setError("Impossible de supprimer cette catégorie : elle contient des sous-catégories.");return;}if(products.some(p=>p.category_id===id)){setError("Impossible de supprimer cette catégorie : elle est utilisée par un ou plusieurs produits.");return;}if(!confirm("Supprimer cette catégorie ?"))return;try{await supabaseRest("categories",{method:"DELETE",query:"?id=eq."+id});setMessage("Catégorie supprimée.");await load();}catch(e){setError(e instanceof Error?e.message:"Suppression impossible");}};
  const saveScreenPrice=async(row:{id?:string;brand:string;model:string;available:boolean;screen_price:number;installation_price:number;notes:string|null})=>{setError("");setMessage("");try{const body={brand:row.brand,model:row.model,available:Boolean(row.available),screen_price:Math.max(0,Number(row.screen_price)||0),installation_price:Math.max(0,Number(row.installation_price)||0),notes:row.notes?.trim()||null,active:true};if(row.id)await supabaseRest("repair_screen_prices",{method:"PATCH",query:"?id=eq."+row.id,body});else await supabaseRest("repair_screen_prices",{method:"POST",body});setMessage("Tarif écran enregistré.");await load();}catch(e){setError(e instanceof Error?e.message:"Impossible d’enregistrer le tarif écran");}};
  const saveRepair=async(e:React.FormEvent)=>{e.preventDefault();setError("");setMessage("");try{const body={device_brand:editingRepair.device_brand.trim()||"Tous",device_model:editingRepair.device_model.trim()||"Tous",service_name:editingRepair.service_name.trim(),estimated_price:Number(editingRepair.estimated_price)||0,repair_time:editingRepair.repair_time||"",available:Boolean(editingRepair.available),slug:editingRepair.slug||null,name:editingRepair.service_name.trim()||editingRepair.name||"",description:editingRepair.description||"",price_from:Number(editingRepair.estimated_price)||0,duration:editingRepair.repair_time||"",active:Boolean(editingRepair.available),sort_order:Number(editingRepair.sort_order)||0};if(!body.service_name)throw new Error("Le nom du service est obligatoire.");if(editingRepair.id)await supabaseRest("repair_services",{method:"PATCH",query:"?id=eq."+editingRepair.id,body});else await supabaseRest("repair_services",{method:"POST",body});setEditingRepair(emptyRepair);setMessage("Service enregistré.");await load();}catch(e){setError(e instanceof Error?e.message:"Erreur");}};
  const deleteRepair=async(id:string)=>{if(!confirm("Supprimer ce service ?"))return;try{await supabaseRest("repair_services",{method:"DELETE",query:"?id=eq."+id});await load();}catch(e){setError(e instanceof Error?e.message:"Suppression impossible");}};
  const updateOrder=async(id:string,status:string)=>{try{await supabaseRest("rpc/admin_update_order_status",{method:"POST",body:{p_order_id:id,p_status:status}});setMessage(status==="confirmed"?"Commande confirmée et stock mis à jour.":status==="cancelled"?"Commande annulée et stock rétabli si nécessaire.":"Statut de commande mis à jour.");await load();}catch(e){setError(e instanceof Error?e.message:"Erreur de mise à jour");}};
  const adjustStock=async()=>{if(!stockProductId)return;setError("");try{await supabaseRest("rpc/admin_stock_adjust",{method:"POST",body:{p_product_id:stockProductId,p_quantity:Math.max(0,Math.floor(Number(stockQuantity)||0)),p_movement_type:stockMovementType,p_reason:stockReason.trim()||null}});setMessage("Mouvement de stock enregistré.");setStockReason("");await load();}catch(e){setError(e instanceof Error?e.message:"Impossible de modifier le stock");}};
  const savePromotion=async(e:React.FormEvent)=>{e.preventDefault();setError("");try{const body={name:editingPromotion.name,description:editingPromotion.description||null,discount_type:editingPromotion.discount_type,discount_value:Number(editingPromotion.discount_value)||0,scope_type:editingPromotion.scope_type,scope_id:editingPromotion.scope_id||null,starts_at:editingPromotion.starts_at||null,ends_at:editingPromotion.ends_at||null,active:Boolean(editingPromotion.active)};if(editingPromotion.id)await supabaseRest("promotions",{method:"PATCH",query:"?id=eq."+editingPromotion.id,body});else await supabaseRest("promotions",{method:"POST",body});setEditingPromotion({id:"",name:"",description:"",discount_type:"percent",discount_value:0,scope_type:"all",scope_id:null,starts_at:null,ends_at:null,active:true});setMessage("Promotion enregistrée.");await load();}catch(e){setError(e instanceof Error?e.message:"Erreur promotion");}};
  const deletePromotion=async(id:string)=>{if(!confirm("Supprimer cette promotion ?"))return;try{await supabaseRest("promotions",{method:"DELETE",query:"?id=eq."+id});setMessage("Promotion supprimée.");await load();}catch(e){setError(e instanceof Error?e.message:"Suppression impossible");}};
  const deleteOrder=async(id:string,reference:string)=>{if(!confirm("Supprimer définitivement la commande "+reference+" ?"))return;try{await supabaseRest("orders",{method:"DELETE",query:"?id=eq."+id});setMessage("Commande supprimée.");await load();}catch(e){setError(e instanceof Error?e.message:"Suppression impossible");}};
  const orderEmail=(o:Order)=>o.email||"—";
  const orderStatusLabel=(status:string)=>({pending_whatsapp:"À confirmer",confirmed:"Confirmée",processing:"En préparation",shipped:"Expédiée",completed:"Terminée",cancelled:"Annulée"} as Record<string,string>)[status]||status;
  const orderStatusClass=(status:string)=>status==="cancelled"?"border-destructive/30 bg-destructive/5 text-destructive":status==="completed"?"border-emerald-500/30 bg-emerald-500/5 text-emerald-400":status==="pending_whatsapp"?"border-gold/30 bg-gold/5 text-gold":"border-border bg-surface text-foreground";
  const filteredOrders=orders.filter(o=>(orderStatusFilter==="all"||o.status===orderStatusFilter)&&((o.reference+" "+o.customer_name+" "+(o.email||"")+" "+o.phone).toLowerCase().includes(orderSearch.toLowerCase())));
  const orderWhatsApp=(o:Order)=>{const phone=o.phone.replace(/\D/g,"");const normalized=phone.startsWith("0")?"212"+phone.slice(1):phone;const lines=(o.items||[]).map(i=>"- "+(i.name||"Produit")+" × "+(i.quantity||1)+" — "+Number(i.price||0).toLocaleString("fr-MA")+" MAD");const text=["Bonjour "+o.customer_name+",","OROTRONIX — Commande "+o.reference,...lines,"Total : "+Number(o.total||0).toLocaleString("fr-MA")+" MAD"].join("\n");window.open("https://wa.me/"+normalized+"?text="+encodeURIComponent(text),"_blank","noopener,noreferrer");};
  const printOrder=(o:Order)=>{const rows=(o.items||[]).map(i=>"<tr><td>"+(i.name||"Produit")+"</td><td>"+(i.quantity||1)+"</td><td>"+Number(i.price||0).toLocaleString("fr-MA")+" MAD</td></tr>").join("");const subtotal=(o.items||[]).reduce((sum,i)=>sum+Number(i.price||0)*Number(i.quantity||0),0);const shipping=Math.max(0,Number(o.total||0)-subtotal);const w=window.open("","_blank");if(!w){setError("Le navigateur bloque la fenêtre d’impression. Autorisez les pop-ups pour le site.");return;}const html="<!doctype html><html lang='fr'><head><meta charset='utf-8'><title>"+o.reference+" | OROTRONIX</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#111;max-width:900px;margin:auto}h1{font-size:28px;margin:0 0 8px}.meta{color:#555;margin-bottom:24px}.box{border:1px solid #ddd;border-radius:10px;padding:16px;margin:16px 0}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}th{background:#f5f5f5} .summary{text-align:right;margin-top:20px}.summary p{margin:6px 0}.total{text-align:right;font-size:20px;font-weight:700;margin-top:10px}.shipping{margin-top:8px;padding:11px 14px;border:1px solid #ddd;border-radius:9px;background:#fafafa;text-align:right;font-size:15px}</style></head><body><h1>OROTRONIX</h1><div class='meta'>Bon de commande — "+o.reference+"<br>"+new Date(o.created_at).toLocaleString("fr-MA")+"</div><div class='box'><b>Client</b><br>"+(o.customer_name||"—")+"<br>"+(o.phone||"—")+"<br>"+(o.email||"—")+"<br>"+(o.address||"—")+(o.city?" · "+o.city:"")+"</div><table><thead><tr><th>Produit</th><th>Qté</th><th>Prix</th></tr></thead><tbody>"+rows+"</tbody></table><div class='summary'><p>Sous-total : <strong>"+subtotal.toLocaleString("fr-MA")+" MAD</strong></p><p class='shipping'>🚚 Livraison : <strong>"+(shipping===0?"Offerte":shipping.toLocaleString("fr-MA")+" MAD")+"</strong></p><p class='total'>Total : "+Number(o.total||0).toLocaleString("fr-MA")+" MAD</p></div>"+(o.notes?"<div class='box'><b>Notes</b><br>"+o.notes+"</div>":"")+"<script>window.onload=function(){setTimeout(function(){window.print()},250)}</script></body></html>";w.document.open();w.document.write(html);w.document.close();};
  const saveSettings=async()=>{if(!settings)return;try{await supabaseRest("store_settings",{method:"PATCH",query:"?id=eq."+settings.id,body:settings});setMessage("Paramètres enregistrés.");}catch(e){setError(e instanceof Error?e.message:"Erreur");}};

  const navItems=[["dashboard","Vue d’ensemble",BarChart3],["products","Produits",Package],["stock","Stock",Warehouse],["categories","Catégories",Tags],["promotions","Promotions",Percent],["orders","Commandes",ShoppingBag],["customers","Clients",CheckCircle2],["loyalty","Fidélité",Star],["repairs","Services",Wrench],["screens","Écrans",Wrench],["repair-requests","Demandes réparation",Wrench],["settings","Paramètres",Zap]] as const;
  return <Shell><div className="w-full max-w-full min-h-[calc(100vh-40px)] overflow-hidden rounded-3xl border border-gold/10 bg-card shadow-2xl shadow-black/20">
    <div className="flex min-h-[calc(100vh-40px)] flex-col lg:flex-row">
      <aside className={(sidebarOpen?"block ":"hidden ")+"w-full shrink-0 border-b border-border bg-background/70 lg:block lg:w-64 lg:border-b-0 lg:border-r"}>
        <div className="flex items-center justify-between border-b border-border p-5"><div><p className="text-xs font-semibold tracking-[0.24em] text-gold">OROTRONIX</p><p className="mt-1 text-xs text-muted-foreground">ADMINISTRATION</p></div><button type="button" aria-label="Fermer le menu" className="flex h-9 w-9 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-surface hover:text-foreground lg:hidden" onClick={()=>setSidebarOpen(false)}><span className="text-xl leading-none">×</span></button></div>
        <nav className="flex gap-1 overflow-x-auto p-3 lg:block">{navItems.map(([id,label,Icon])=><button key={id} type="button" onClick={()=>setTab(id)} className={"flex min-w-max items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition-colors lg:mb-1 lg:w-full "+(tab===id?"bg-gold/10 text-gold":"text-muted-foreground hover:bg-surface hover:text-foreground")}><Icon className="h-4 w-4 shrink-0"/><span>{label}</span></button>)}</nav>
        <div className="mt-auto hidden border-t border-border p-3 lg:block"><button type="button" onClick={logout} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-muted-foreground hover:bg-surface hover:text-foreground"><LogOut className="h-4 w-4"/>Déconnexion</button></div>
      </aside>
      <section className="min-w-0 flex-1 p-4 sm:p-6 lg:p-8">
        <header className="mb-6 flex flex-col gap-4 border-b border-border pb-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 items-center gap-3"><button type="button" aria-label="Ouvrir le menu" className={(sidebarOpen?"hidden ":"flex ")+"h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-border bg-surface text-muted-foreground hover:text-foreground lg:hidden"} onClick={()=>setSidebarOpen(true)}>☰</button><div className="min-w-0"><p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-gold">OROTRONIX · ADMIN</p><h1 className="mt-2 font-display text-2xl font-bold sm:text-3xl">{navItems.find(x=>x[0]===tab)?.[1]}</h1><p className="mt-1 text-sm text-muted-foreground">Gestion centralisée de votre boutique.</p></div><div className="flex gap-2"><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className={"mr-2 h-4 w-4 "+(loading?"animate-spin":"")}/>Actualiser</Button><Button variant="outline" className="lg:hidden" onClick={logout}><LogOut className="mr-2 h-4 w-4"/>Sortir</Button></div></div></header>
        {error&&<div role="alert" className="mb-4 rounded-xl border border-destructive/40 bg-destructive/5 p-4 text-sm text-destructive">{error}</div>}{message&&<div className="mb-4 rounded-xl border border-gold/30 bg-gold/5 p-4 text-sm text-gold">{message}</div>}
    {tab==="dashboard"&&<DashboardOverview products={products} categories={categories} repairs={repairs} orders={dashboardOrders} period={dashboardPeriod} setPeriod={setDashboardPeriod}/>}
    {tab==="products"&&<section className="grid w-full min-w-0 gap-6 lg:grid-cols-[minmax(0,1fr)_420px]">
  <div className="min-w-0 overflow-hidden rounded-2xl border border-border bg-card">
    <div className="space-y-4 border-b border-border p-5">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div><h2 className="font-display text-lg font-semibold">Produits ({filteredProducts.length})</h2><p className="mt-1 text-xs text-muted-foreground">Gérez les informations, le prix, le stock et la visibilité de chaque produit.</p></div>
        <Button type="button" onClick={()=>{setEditing(emptyProduct);setProductEditRequest(v=>v+1);}}><Plus className="mr-2 h-4 w-4"/>Ajouter un produit</Button>
        <Input className="bg-surface sm:max-w-xs" placeholder="Rechercher un produit…" value={productSearch} onChange={e=>setProductSearch(e.target.value)}/>
      </div>
      <div className="grid grid-cols-1 gap-2 sm:grid-cols-3">
        <select aria-label="Filtrer par catégorie" className="h-9 rounded-md border border-border bg-surface px-3 text-sm" value={productCategoryFilter} onChange={e=>setProductCategoryFilter(e.target.value)}><option value="all">Toutes les catégories</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>
        <select aria-label="Filtrer par stock" className="h-9 rounded-md border border-border bg-surface px-3 text-sm" value={productStockFilter} onChange={e=>setProductStockFilter(e.target.value)}><option value="all">Tous les stocks</option><option value="in">En stock</option><option value="out">Rupture</option></select>
        <select aria-label="Trier les produits" className="h-9 rounded-md border border-border bg-surface px-3 text-sm" value={productSort} onChange={e=>setProductSort(e.target.value)}><option value="newest">Plus récents</option><option value="name">Nom A–Z</option><option value="price-low">Prix croissant</option><option value="price-high">Prix décroissant</option></select>
      </div>
    </div>
    <div className="border-b border-border bg-surface/50 p-3"><div className="flex flex-wrap items-center gap-2">
      <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={filteredProducts.length>0&&filteredProducts.every(p=>selectedProducts.includes(p.id))} onChange={toggleAllFiltered}/> Tout sélectionner</label>
      {selectedProducts.length>0&&<><span className="text-xs text-muted-foreground">{selectedProducts.length} sélectionné(s)</span><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("show")}><Eye className="mr-1 h-4 w-4"/>Afficher</Button><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("hide")}><EyeOff className="mr-1 h-4 w-4"/>Masquer</Button><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("stock1")}>+1 stock</Button><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("stock0")}>Rupture</Button><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("featured")}>Vedette</Button><Button size="sm" variant="outline" disabled={productBulkBusy} onClick={()=>void bulkProducts("unfeatured")}>Retirer vedette</Button></>}
    </div></div>
    <div className="divide-y divide-border">
      {filteredProducts.map(p=>{const category=categories.find(c=>c.id===p.category_id)?.name||"Sans catégorie";const stockLabel=p.stock_quantity===0?"Rupture":p.stock_quantity<=p.low_stock_threshold?"Stock faible":"En stock";return <div key={p.id} className="p-4 transition-colors hover:bg-surface/30 sm:p-5">
        <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_auto] xl:items-center">
          <div className="flex min-w-0 items-start gap-3">
            <input className="mt-1" type="checkbox" checked={selectedProducts.includes(p.id)} onChange={()=>toggleProduct(p.id)} aria-label={"Sélectionner "+p.name}/>
            <div className="h-16 w-16 shrink-0 overflow-hidden rounded-xl border border-border bg-surface">{p.image_url?<img src={p.image_url} alt={p.name} className="h-full w-full object-cover"/>:<div className="flex h-full w-full items-center justify-center text-[10px] text-muted-foreground">Pas d’image</div>}</div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2"><p className="break-words font-semibold">{p.name||"Produit sans nom"}</p>{p.featured&&<span className="rounded-full border border-gold/30 bg-gold/10 px-2 py-0.5 text-[10px] text-gold">Vedette</span>}<span className={"rounded-full border px-2 py-0.5 text-[10px] "+(p.visible?"border-emerald-500/30 bg-emerald-500/5 text-emerald-400":"border-border bg-surface text-muted-foreground")}>{p.visible?"Visible":"Masqué"}</span></div>
              <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground"><span>Catégorie : {category}</span>{p.brand&&<span>Marque : {p.brand}</span>}{p.sku&&<span>SKU : {p.sku}</span>}</div>
              <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-2"><span className="font-semibold text-gold">{Number(p.price||0).toLocaleString("fr-MA")} MAD</span>{p.old_price!=null&&p.old_price>p.price&&<span className="text-xs text-muted-foreground line-through">{Number(p.old_price).toLocaleString("fr-MA")} MAD</span>}{p.promo_price!=null&&<span className="text-xs text-emerald-400">Promo : {Number(p.promo_price).toLocaleString("fr-MA")} MAD</span>}<span className={"text-xs "+(p.stock_quantity===0?"text-destructive":p.stock_quantity<=p.low_stock_threshold?"text-gold":"text-emerald-400")}>{stockLabel} · {p.stock_quantity} unité(s)</span></div>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 xl:justify-end">
            <div className="flex items-center rounded-lg border border-border bg-surface"><Button type="button" size="icon" variant="ghost" className="h-9 w-9" aria-label={"Diminuer le stock de "+p.name} disabled={p.stock_quantity===0} onClick={()=>void quickStock(p,-1)}><Minus className="h-3.5 w-3.5"/></Button><span className="min-w-10 text-center text-xs font-semibold">{p.stock_quantity}</span><Button type="button" size="icon" variant="ghost" className="h-9 w-9" aria-label={"Augmenter le stock de "+p.name} onClick={()=>void quickStock(p,1)}><Plus className="h-3.5 w-3.5"/></Button></div>
            <Button size="sm" variant="outline" onClick={()=>{setEditing({...p,highlights:p.highlights||[]});setProductEditRequest(v=>v+1);}}><Eye className="mr-1 h-4 w-4"/>Modifier</Button>
            <Button size="icon" variant="outline" aria-label={"Dupliquer "+p.name} onClick={()=>void duplicateProduct(p)}><Copy className="h-4 w-4"/></Button>
            <Button size="icon" variant="ghost" className="text-destructive hover:text-destructive" aria-label={"Supprimer "+p.name} onClick={()=>void deleteProduct(p.id)}><Trash2 className="h-4 w-4"/></Button>
          </div>
        </div>
      </div>})}
      {filteredProducts.length===0&&<div className="p-8 text-center text-sm text-muted-foreground">Aucun produit ne correspond aux filtres.</div>}
    </div>
  </div>
  <div ref={productFormRef} className="scroll-mt-6"><ProductForm value={editing} categories={categories} onChange={setEditing} onSubmit={saveProduct} onCancel={()=>setEditing(emptyProduct)}/></div>
</section>}{tab==="categories"&&<section className="grid gap-6 lg:grid-cols-[1fr_420px]"><div className="rounded-2xl border border-border bg-card"><div className="flex items-center justify-between gap-3 border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Catégories ({categories.length})</h2><Button type="button" size="sm" onClick={()=>{setEditingCategory(emptyCategory);setCategoryEditRequest(v=>v+1);}}><Plus className="mr-1 h-4 w-4"/>Ajouter une catégorie</Button></div><div className="divide-y divide-border">{categories.map(x=><div key={x.id} className="flex items-center justify-between gap-3 p-4"><div className="flex min-w-0 items-center gap-3 pr-2"><div className="h-16 w-16 shrink-0 overflow-hidden rounded-xl border border-border bg-surface">{x.image_url?<img src={x.image_url} alt={x.name} className="h-full w-full object-cover"/>:<div className="flex h-full w-full items-center justify-center text-[10px] text-muted-foreground">Pas d’image</div>}</div><div className="min-w-0"><p className="break-words font-medium">{x.name}</p><p className="text-xs text-muted-foreground">{x.slug}</p>{x.description&&<p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{x.description}</p>}</div></div><div className="flex shrink-0 gap-1"><Button size="sm" variant="outline" onClick={()=>{setEditingCategory(x);setCategoryEditRequest(v=>v+1);}}>Modifier</Button><Button size="icon" variant="ghost" aria-label={"Supprimer "+x.name} onClick={()=>void deleteCategory(x.id)}><Trash2 className="h-4 w-4"/></Button></div></div>)}</div></div><div ref={categoryFormRef} className="scroll-mt-6"><CategoryForm value={editingCategory} categories={categories} onChange={setEditingCategory} onSubmit={saveCategory} onCancel={()=>setEditingCategory(emptyCategory)}/></div></section>}{tab==="stock"&&<section className="mx-auto w-full min-w-0 max-w-6xl space-y-5"><div className="mx-auto w-full max-w-6xl min-w-0 space-y-5"><div className="w-full min-w-0 overflow-hidden rounded-2xl border border-border bg-card"><div><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">État du stock</h2><p className="mt-1 text-xs text-muted-foreground">Recherche, alertes et quantité actuelle.</p></div><div className="divide-y divide-border">{products.filter(p=>p.name.toLowerCase().includes(productSearch.toLowerCase())).map(p=><div key={p.id} className="flex items-center justify-between gap-3 p-4"><div className="min-w-0"><p className="truncate font-medium">{p.name}</p><p className="text-xs text-muted-foreground">{p.sku||"Sans SKU"} · {p.stock_quantity===0?"Rupture":p.stock_quantity<=p.low_stock_threshold?"Stock faible":"Disponible"}</p></div><div className="flex shrink-0 items-center gap-2"><strong className="min-w-10 text-center">{p.stock_quantity}</strong><Button size="icon" variant="outline" aria-label="Sortie stock" disabled={p.stock_quantity===0} onClick={()=>void quickStock(p,-1)}><ArrowDownToLine className="h-4 w-4"/></Button><Button size="icon" variant="outline" aria-label="Entrée stock" onClick={()=>void quickStock(p,1)}><ArrowUpFromLine className="h-4 w-4"/></Button></div></div>)}</div></div><div className="w-full min-w-0 overflow-hidden rounded-2xl border border-gold/20 bg-card p-5"><h2 className="font-display text-lg font-semibold">Mouvement de stock</h2><p className="mt-1 text-xs text-muted-foreground">Une seule action pour entrée, sortie ou inventaire.</p><div className="mt-4 space-y-3"><div><Label>Produit</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={stockProductId} onChange={e=>setStockProductId(e.target.value)}><option value="">Choisir un produit</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} · {p.stock_quantity}</option>)}</select></div><div><Label>Opération</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={stockMovementType} onChange={e=>setStockMovementType(e.target.value)}><option value="in">Entrée</option><option value="out">Sortie</option><option value="return">Retour</option><option value="sale">Vente</option><option value="adjustment">Inventaire — définir quantité</option></select></div><Field label={stockMovementType==="adjustment"?"Nouvelle quantité":"Quantité"} value={String(stockQuantity)} onChange={v=>setStockQuantity(Number(v)||0)} type="number"/><Field label="Motif / note" value={stockReason} onChange={setStockReason} required={false}/><Button className="w-full" onClick={()=>void adjustStock()} disabled={!stockProductId}><Save className="mr-2 h-4 w-4"/>Enregistrer le mouvement</Button></div></div></div></div><div className="w-full min-w-0 overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center gap-2 border-b border-border p-5"><History className="h-5 w-5 text-gold"/><div><h2 className="font-display text-lg font-semibold">Historique des mouvements</h2><p className="text-xs text-muted-foreground">Les 100 dernières opérations.</p></div></div><div className="divide-y divide-border">{stockMovements.map(m=>{const p=products.find(x=>x.id===m.product_id);return <div key={m.id} className="grid min-w-0 gap-2 p-4 sm:grid-cols-[minmax(0,1fr)_auto_auto_minmax(110px,auto)] sm:items-center"><div><p className="font-medium">{p?.name||"Produit supprimé"}</p><p className="text-xs text-muted-foreground">{m.reason||"—"} · {new Date(m.created_at).toLocaleString("fr-MA")}</p></div><span className="text-xs">{m.movement_type}</span><span className={m.quantity>=0?"text-emerald-400":"text-destructive"}>{m.quantity>=0?"+":""}{m.quantity}</span><span className="text-xs text-muted-foreground">{m.previous_quantity} → {m.new_quantity}</span></div>})}{stockMovements.length===0&&<p className="p-6 text-sm text-muted-foreground">Aucun mouvement enregistré.</p>}</div></div></section>}{tab==="promotions"&&<section className="grid gap-6 lg:grid-cols-[1fr_420px]"><div className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Promotions ({promotions.length})</h2><p className="mt-1 text-xs text-muted-foreground">Créez des campagnes par boutique, catégorie ou produit.</p></div><div className="divide-y divide-border">{promotions.map(p=><div key={p.id} className="flex items-center justify-between gap-3 p-4"><div><p className="font-medium">{p.name}</p><p className="text-xs text-muted-foreground">{p.discount_type==="percent"?p.discount_value+" %":"-"+p.discount_value+" MAD"} · {p.scope_type==="all"?"Toute la boutique":p.scope_type==="category"?categories.find(c=>c.id===p.scope_id)?.name||"Catégorie":"Produit"}</p><p className="text-xs text-muted-foreground">{p.active?"Active":"Désactivée"}{p.ends_at?" · jusqu’au "+new Date(p.ends_at).toLocaleDateString("fr-MA"):""}</p></div><div className="flex gap-1"><Button size="sm" variant="outline" onClick={()=>setEditingPromotion(p)}>Modifier</Button><Button size="icon" variant="ghost" onClick={()=>void deletePromotion(p.id)} aria-label={"Supprimer "+p.name}><Trash2 className="h-4 w-4"/></Button></div></div>)}{promotions.length===0&&<p className="p-6 text-sm text-muted-foreground">Aucune promotion.</p>}</div></div><PromotionForm value={editingPromotion} categories={categories} products={products} onChange={setEditingPromotion} onSubmit={savePromotion} onCancel={()=>setEditingPromotion({id:"",name:"",description:"",discount_type:"percent",discount_value:0,scope_type:"all",scope_id:null,starts_at:null,ends_at:null,active:true})}/></section>}
    {tab==="loyalty"&&<AdminLoyaltyPanel/>}
    {tab==="repair-requests"&&<RepairRequestsPanel/>}
    {tab==="screens"&&<ScreenPricesPanel screenPrices={screenPrices} search={screenSearch} setSearch={setScreenSearch} onSave={saveScreenPrice}/>}
    {tab==="repairs"&&<section className="grid gap-6 lg:grid-cols-[1fr_420px]"><div className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Services de réparation</h2></div><div className="divide-y divide-border">{repairs.map(x=><div key={x.id} className="flex items-start justify-between gap-3 p-4"><div className="min-w-0 pr-2"><p className="font-medium">{x.name}</p><p className="text-xs text-muted-foreground">{x.device_brand} · {x.device_model} · À partir de {Number(x.estimated_price ?? x.price_from ?? 0).toLocaleString("fr-MA")} MAD · {x.available ? "Disponible" : "Masqué"}</p></div><div className="flex shrink-0 gap-1"><Button size="sm" variant="outline" onClick={()=>setEditingRepair(x)}>Modifier</Button><Button size="icon" variant="ghost" aria-label={"Supprimer "+x.name} onClick={()=>void deleteRepair(x.id)}><Trash2 className="h-4 w-4"/></Button></div></div>)}</div></div><RepairForm value={editingRepair} onChange={setEditingRepair} onSubmit={saveRepair} onCancel={()=>setEditingRepair(emptyRepair)}/></section>}
    {tab==="orders"&&<section className="space-y-4">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {[
          ["À confirmer",orders.filter(o=>o.status==="pending_whatsapp").length,"pending_whatsapp"],
          ["En cours",orders.filter(o=>["confirmed","processing","shipped"].includes(o.status)).length,"processing"],
          ["Terminées",orders.filter(o=>o.status==="completed").length,"completed"],
          ["Annulées",orders.filter(o=>o.status==="cancelled").length,"cancelled"]
        ].map(([label,count,status])=><button key={String(status)} type="button" onClick={()=>setOrderStatusFilter(String(status))} className={"rounded-2xl border p-4 text-left transition-colors hover:border-gold/30 "+orderStatusClass(String(status))}><p className="text-xs uppercase tracking-wider opacity-80">{String(label)}</p><p className="mt-2 font-display text-2xl font-bold">{String(count)}</p></button>)}
      </div>
      <section className="rounded-2xl border border-border bg-card">
        <div className="border-b border-border p-5 space-y-3">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2"><div><h2 className="font-display text-lg font-semibold">Commandes ({filteredOrders.length})</h2><p className="mt-1 text-xs text-muted-foreground">Suivi, confirmation et traitement des commandes.</p></div><Button size="sm" variant="outline" onClick={exportOrders}><Download className="mr-1 h-4 w-4"/>Exporter CSV</Button></div>
            <Input className="bg-surface sm:max-w-xs" placeholder="Rechercher commande, nom ou téléphone…" value={orderSearch} onChange={e=>setOrderSearch(e.target.value)}/>
          </div>
          <div className="flex flex-col gap-2 sm:flex-row">
            <select aria-label="Filtrer les commandes par statut" className="h-9 w-full rounded-md border border-border bg-surface px-3 text-sm sm:max-w-xs" value={orderStatusFilter} onChange={e=>setOrderStatusFilter(e.target.value)}><option value="all">Tous les statuts</option><option value="pending_whatsapp">À confirmer</option><option value="confirmed">Confirmée</option><option value="processing">En préparation</option><option value="shipped">Expédiée</option><option value="completed">Terminée</option><option value="cancelled">Annulée</option></select>
            {orderStatusFilter!=="all"&&<Button size="sm" variant="ghost" onClick={()=>setOrderStatusFilter("all")}>Réinitialiser</Button>}
          </div>
        </div>
        <div className="divide-y divide-border">{filteredOrders.map(o=><div key={o.id} className="p-4 sm:p-5">
          <div className="grid gap-4 xl:grid-cols-[1fr_auto] xl:items-center">
            <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{o.reference}</p><span className={"rounded-full border px-2.5 py-1 text-[11px] font-medium "+orderStatusClass(o.status)}>{orderStatusLabel(o.status)}</span></div>
              <p className="mt-1 text-sm">{o.customer_name}</p><p className="text-xs text-muted-foreground">{o.email||"E-mail non renseigné"} · {o.phone}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(o.created_at).toLocaleString("fr-MA")}</p>{o.notes&&<p className="mt-2 rounded-lg bg-surface p-2 text-xs text-muted-foreground">{o.notes}</p>}
            </div>
            <div className="flex flex-wrap items-center gap-2 xl:justify-end"><strong className="mr-1 text-sm">{Number(o.total||0).toLocaleString("fr-MA")} MAD</strong><select aria-label={"Statut "+o.reference} className="h-9 rounded-md border border-border bg-surface px-3 text-sm" value={o.status} onChange={e=>void updateOrder(o.id,e.target.value)}><option value="pending_whatsapp">À confirmer</option><option value="confirmed">Confirmée</option><option value="processing">En préparation</option><option value="shipped">Expédiée</option><option value="completed">Terminée</option><option value="cancelled">Annulée</option></select><Button size="sm" variant="outline" onClick={()=>orderWhatsApp(o)}>WhatsApp</Button><Button size="sm" variant="outline" onClick={()=>printOrder(o)}>Imprimer</Button><a className="inline-flex h-9 items-center rounded-md border border-border px-3 text-sm hover:bg-surface" href={"tel:"+o.phone}>Appeler</a><Button size="icon" variant="ghost" aria-label={"Supprimer la commande "+o.reference} onClick={()=>void deleteOrder(o.id,o.reference)}><Trash2 className="h-4 w-4"/></Button></div>
          </div>
          <details className="mt-4 rounded-xl border border-border bg-surface p-3"><summary className="cursor-pointer text-sm font-medium">Voir les détails · {(o.items||[]).length} article(s)</summary><div className="mt-3 grid gap-4 lg:grid-cols-2"><div><p className="text-xs uppercase tracking-wider text-muted-foreground">Livraison</p><p className="mt-1 text-sm">{o.email||"E-mail non renseigné"}</p><p className="mt-1 text-sm">{o.address||"—"}{o.city?" · "+o.city:""}</p></div><div><p className="text-xs uppercase tracking-wider text-muted-foreground">Articles</p><div className="mt-2 space-y-2">{(o.items||[]).length?o.items.map((i,idx)=><div key={i.id||idx} className="flex items-center justify-between gap-3 rounded-lg bg-background/50 p-2 text-sm"><span>{i.name||"Produit"} × {i.quantity||1}</span><span className="font-medium">{Number(i.price||0).toLocaleString("fr-MA")} MAD</span></div>):<span className="text-sm text-muted-foreground">Aucun détail disponible.</span>}</div></div></div></details>
        </div>)}{filteredOrders.length===0&&<div className="p-8 text-center"><p className="font-medium">Aucune commande trouvée</p><p className="mt-1 text-sm text-muted-foreground">Essayez un autre filtre ou une autre recherche.</p></div>}
        </div>
      </section>
    </section>}
    {tab==="customers"&&<section className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-display text-lg font-semibold">Clients ({customers.length})</h2><p className="mt-1 text-xs text-muted-foreground">Comptes créés sur le site OROTRONIX.</p></div><Input className="bg-surface sm:max-w-xs" placeholder="Rechercher par e-mail…" value={customerSearch} onChange={e=>setCustomerSearch(e.target.value)}/></div></div><div className="divide-y divide-border">{customers.filter(c=>((c.email||"")+" "+(c.full_name||"")+" "+(c.phone||"")+" "+(c.city||"")).toLowerCase().includes(customerSearch.toLowerCase())).map(c=><div key={c.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><p className="font-medium">{c.full_name||c.email||"Client"}</p><p className="text-sm text-muted-foreground">{c.email||"E-mail non renseigné"}{c.phone?" · "+c.phone:""}{c.city?" · "+c.city:""}</p><p className="text-xs text-muted-foreground">Inscrit le {new Date(c.created_at).toLocaleString("fr-MA")}{c.last_sign_in_at?" · Dernière connexion "+new Date(c.last_sign_in_at).toLocaleString("fr-MA"):""}</p></div><div className="grid grid-cols-3 gap-4 text-left lg:text-right"><div><p className="text-xs text-muted-foreground">Commandes</p><p className="text-sm font-semibold">{c.order_count}</p></div><div><p className="text-xs text-muted-foreground">Achats</p><p className="text-sm font-semibold text-gold">{Number(c.total_spent||0).toLocaleString("fr-MA")} MAD</p></div><div><p className="text-xs text-muted-foreground">Dernière</p><p className="text-xs">{c.last_order_at?new Date(c.last_order_at).toLocaleDateString("fr-MA"):"—"}</p></div></div></div>)}</div></section>}
    {tab==="settings"&&settings&&<section className="max-w-2xl rounded-2xl border border-border bg-card p-6 space-y-4"><h2 className="font-display text-lg font-semibold">Paramètres de la boutique</h2><Field label="Nom" value={settings.store_name} onChange={v=>setSettings({...settings,store_name:v})}/><Field label="WhatsApp" value={settings.whatsapp} onChange={v=>setSettings({...settings,whatsapp:v})}/><Field label="Téléphone" value={settings.phone} onChange={v=>setSettings({...settings,phone:v})}/><Field label="Adresse" value={settings.address} onChange={v=>setSettings({...settings,address:v})}/><Field label="Horaires" value={settings.hours} onChange={v=>setSettings({...settings,hours:v})}/><div><Label>Banner</Label><Textarea className="mt-2 bg-surface" value={settings.banner||""} onChange={e=>setSettings({...settings,banner:e.target.value})}/></div><Button onClick={()=>void saveSettings()}><Save className="mr-2 h-4 w-4"/>Enregistrer</Button></section>}
      </section>
    </div>
  </div></Shell>;
}

function DashboardOverview({products,categories,repairs,orders,period,setPeriod}:{products:Product[];categories:Category[];repairs:Repair[];orders:Order[];period:"all"|"today"|"7d"|"30d";setPeriod:(v:"all"|"today"|"7d"|"30d")=>void}) {
  const pendingOrders=orders.filter(o=>o.status==="pending_whatsapp");
  const processingOrders=orders.filter(o=>o.status==="processing");
  const confirmedOrders=orders.filter(o=>["confirmed","processing","shipped","completed"].includes(o.status));
  const totalValue=confirmedOrders.reduce((sum,o)=>sum+Number(o.total||0),0);
  const activeProducts=products.filter(p=>p.in_stock).length;
  const lowStock=products.filter(p=>p.stock_quantity>0&&p.stock_quantity<=p.low_stock_threshold);
  const outOfStock=products.filter(p=>p.stock_quantity===0);
  const recentOrders=[...orders].sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()).slice(0,6);
  const stats=[
    {label:"Produits",value:products.length,detail:activeProducts+" disponibles",icon:Package},
    {label:"Commandes",value:orders.length,detail:pendingOrders.length+" à confirmer",icon:ShoppingBag},
    {label:"En préparation",value:processingOrders.length,detail:"commandes en cours",icon:Clock3},
    {label:"Chiffre commandes",value:totalValue.toLocaleString("fr-MA")+" MAD",detail:"confirmées / traitées",icon:BarChart3},
  ];
  return <section className="space-y-6">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <div><p className="text-sm text-muted-foreground">Vue rapide de l’activité de la boutique.</p><p className="mt-1 text-xs text-muted-foreground">Période sélectionnée : {period==="all"?"Toutes les commandes":period==="today"?"Aujourd’hui":period==="7d"?"7 derniers jours":"30 derniers jours"}</p></div>
      <select aria-label="Période du tableau de bord" className="h-10 rounded-md border border-border bg-surface px-3 text-sm" value={period} onChange={e=>setPeriod(e.target.value as "all"|"today"|"7d"|"30d")}><option value="all">Toutes les commandes</option><option value="today">Aujourd’hui</option><option value="7d">7 derniers jours</option><option value="30d">30 derniers jours</option></select>
    </div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      {stats.map(s=>{const Icon=s.icon;return <div key={s.label} className="rounded-2xl border border-border bg-card p-5">
        <div className="flex items-center justify-between gap-3"><p className="text-sm text-muted-foreground">{s.label}</p><Icon className="h-5 w-5 text-gold"/></div><p className="mt-3 font-display text-2xl font-bold">{s.value}</p><p className="mt-1 text-xs text-muted-foreground">{s.detail}</p>
      </div>})}
    </div>
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
      <div className="rounded-2xl border border-gold/25 bg-gold/5 p-5"><p className="text-sm text-muted-foreground">À confirmer</p><p className="mt-2 font-display text-2xl font-bold text-gold">{pendingOrders.length}</p><p className="mt-1 text-xs text-muted-foreground">commandes WhatsApp</p></div>
      <div className="rounded-2xl border border-border bg-card p-5"><p className="text-sm text-muted-foreground">Stock faible</p><p className="mt-2 font-display text-2xl font-bold">{lowStock.length}</p><p className="mt-1 text-xs text-muted-foreground">à réapprovisionner</p></div>
      <div className="rounded-2xl border border-border bg-card p-5"><p className="text-sm text-muted-foreground">Ruptures</p><p className="mt-2 font-display text-2xl font-bold">{outOfStock.length}</p><p className="mt-1 text-xs text-muted-foreground">produits indisponibles</p></div>
      <div className="rounded-2xl border border-border bg-card p-5"><p className="text-sm text-muted-foreground">Clients actifs</p><p className="mt-2 font-display text-2xl font-bold">—</p><p className="mt-1 text-xs text-muted-foreground">détails dans Clients</p></div>
    </div>
    <div className="grid gap-6 lg:grid-cols-[1.35fr_1fr]">
      <div className="rounded-2xl border border-border bg-card">
        <div className="flex items-center justify-between gap-3 border-b border-border p-5"><div><h2 className="font-display text-lg font-semibold">Dernières commandes</h2><p className="mt-1 text-xs text-muted-foreground">Les 6 dernières commandes reçues.</p></div><button type="button" className="text-xs text-gold hover:underline" onClick={()=>setPeriod(period)}>Actualisé</button></div>
        <div className="divide-y divide-border">{recentOrders.map(o=><div key={o.id} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium">{o.reference} · {o.customer_name}</p><p className="text-xs text-muted-foreground">{new Date(o.created_at).toLocaleString("fr-MA")} · {o.phone}</p></div><div className="text-left sm:text-right"><p className="font-semibold">{Number(o.total||0).toLocaleString("fr-MA")} MAD</p><p className="text-xs text-gold">{o.status}</p></div></div>)}{recentOrders.length===0&&<p className="p-5 text-sm text-muted-foreground">Aucune commande.</p>}</div>
      </div>
      <div className="rounded-2xl border border-border bg-card">
        <div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">État du catalogue</h2><p className="mt-1 text-xs text-muted-foreground">Indicateurs à surveiller.</p></div>
        <div className="space-y-3 p-5">
          <div className="flex items-center justify-between rounded-xl bg-surface p-4"><span className="text-sm">Produits</span><strong>{products.length}</strong></div>
          <div className="flex items-center justify-between rounded-xl bg-surface p-4"><span className="text-sm">Catégories</span><strong>{categories.length}</strong></div>
          <div className="flex items-center justify-between rounded-xl bg-surface p-4"><span className="text-sm">Réparations actives</span><strong>{repairs.filter(r=>r.active).length}</strong></div>
          <div className="flex items-center justify-between rounded-xl bg-surface p-4"><span className="text-sm">Produits vedettes</span><strong>{products.filter(p=>p.featured).length}</strong></div>
        </div>
      </div>
    </div>
    <div className="rounded-2xl border border-border bg-card p-5">
      <div className="flex items-center gap-2"><CheckCircle2 className="h-5 w-5 text-gold"/><h2 className="font-display text-lg font-semibold">Alertes stock</h2></div>
      <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{[...lowStock,...outOfStock].slice(0,9).map(p=><div key={p.id} className="flex items-center justify-between gap-3 rounded-xl border border-border bg-surface p-3"><div className="min-w-0"><p className="truncate text-sm font-medium">{p.name}</p><p className="text-xs text-muted-foreground">{p.stock_quantity===0?"Rupture":"Stock faible · "+p.stock_quantity+" restant(s)"}</p></div><span className="text-xs text-gold">{p.stock_quantity}</span></div>)}{lowStock.length===0&&outOfStock.length===0&&<p className="text-sm text-muted-foreground">Aucune alerte stock.</p>}</div>
    </div>
  </section>;
}
function ProductForm({value,categories,onChange,onSubmit,onCancel}:{value:Omit<Product,"id">&{id?:string};categories:Category[];onChange:(v:any)=>void;onSubmit:(e:React.FormEvent)=>void;onCancel:()=>void}) {
  const [uploading,setUploading]=useState(false);
  const [uploadError,setUploadError]=useState("");
  const margin=Number(value.price||0)-Number(value.cost_price||0);
  const marginPct=Number(value.price)>0?(margin/Number(value.price))*100:0;
  const handleImage=async(e:React.ChangeEvent<HTMLInputElement>)=>{
    const file=e.target.files?.[0];
    if(!file)return;
    setUploading(true);setUploadError("");
    try{onChange({...value,image_url:await uploadProductImage(file,"products")});}
    catch(err){setUploadError(err instanceof Error?err.message:"Upload impossible");}
    finally{setUploading(false);e.target.value="";}
  };
  return (
    <form onSubmit={onSubmit} className="space-y-5 rounded-2xl border border-border bg-card p-4 sm:p-6">
      <div>
        <h2 className="font-display text-lg font-semibold">{value.id?"Modifier":"Nouveau"} produit</h2>
        <p className="mt-1 text-xs text-muted-foreground">Fiche produit complète · prix, marge, stock et visibilité.</p>
      </div>
      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Nom" value={value.name} onChange={v=>onChange({...value,name:v})}/>
        <Field label="SKU / Référence" value={value.sku||""} onChange={v=>onChange({...value,sku:v})} required={false}/>
        <Field label="Slug" value={value.slug} onChange={v=>onChange({...value,slug:v})} required={false}/>
        <Field label="Marque" value={value.brand||""} onChange={v=>onChange({...value,brand:v})} required={false}/>
      </div>
      <div>
        <Label>Catégorie <span className="text-destructive">*</span></Label>
        <select required className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.category_id||""} onChange={e=>onChange({...value,category_id:e.target.value||null})}>
          <option value="" disabled>Sélectionner une catégorie</option>
          {categories.filter(c=>c.visible).map(c=><option key={c.id} value={c.id}>{c.parent_id?"↳ ":""}{c.name}</option>)}
        </select>
      </div>
      <div className="grid gap-3 sm:grid-cols-3">
        <Field label="Prix de vente (MAD)" value={String(value.price)} onChange={v=>onChange({...value,price:Number(v)||0})} type="number"/>
        <Field label="Prix d'achat" value={String(value.cost_price||0)} onChange={v=>onChange({...value,cost_price:Number(v)||0})} type="number"/>
        <div className="rounded-lg border border-border bg-surface p-3">
          <p className="text-xs text-muted-foreground">Marge estimée</p>
          <p className="mt-1 font-semibold">{margin.toLocaleString("fr-MA")} MAD</p>
          <p className="text-xs text-gold">{marginPct.toFixed(1)} %</p>
        </div>
      </div>
      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Ancien prix" value={value.old_price==null?"":String(value.old_price)} onChange={v=>onChange({...value,old_price:v===""?null:Number(v)||0})} type="number" required={false}/>
        <Field label="Fournisseur" value={value.supplier||""} onChange={v=>onChange({...value,supplier:v})} required={false}/>
      </div>
      <div className="rounded-xl border border-gold/20 bg-gold/5 p-4">
        <div className="flex items-center gap-2"><Percent className="h-4 w-4 text-gold"/><p className="text-sm font-semibold">Promotion produit</p></div>
        <div className="mt-3 grid gap-3 sm:grid-cols-2">
          <Field label="Prix promotionnel" value={value.promo_price==null?"":String(value.promo_price)} onChange={v=>onChange({...value,promo_price:v===""?null:Number(v)||0})} type="number" required={false}/>
          <Field label="Libellé" value={value.promo_label||""} onChange={v=>onChange({...value,promo_label:v})} required={false}/>
          <Field label="Début" value={value.promo_starts_at?value.promo_starts_at.slice(0,16):""} onChange={v=>onChange({...value,promo_starts_at:v?new Date(v).toISOString():null})} type="datetime-local" required={false}/>
          <Field label="Fin" value={value.promo_ends_at?value.promo_ends_at.slice(0,16):""} onChange={v=>onChange({...value,promo_ends_at:v?new Date(v).toISOString():null})} type="datetime-local" required={false}/>
        </div>
      </div>
      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Quantité en stock" value={String(value.stock_quantity)} onChange={v=>{const n=Number(v);const q=v===""?0:Number.isFinite(n)?Math.max(0,Math.floor(n)):0;onChange({...value,stock_quantity:q,in_stock:q>0});}} type="number"/>
        <Field label="Seuil stock faible" value={String(value.low_stock_threshold)} onChange={v=>onChange({...value,low_stock_threshold:Math.max(0,Number(v)||0)})} type="number"/>
      </div>
      <div>
        <Label>Image du produit</Label>
        <div className="mt-2 flex flex-col gap-3 sm:flex-row">
          <Input type="file" accept="image/*" onChange={handleImage} disabled={uploading} className="bg-surface"/>
          {value.image_url ? <img src={value.image_url} alt="" className="h-20 w-20 rounded-lg border border-border object-cover"/> : null}
        </div>
        {uploading ? <p className="mt-2 text-xs text-muted-foreground">Téléversement en cours…</p> : null}
        {uploadError ? <p className="mt-2 text-xs text-destructive">{uploadError}</p> : null}
        <Input className="mt-3 bg-surface" placeholder="Ou collez une URL d'image existante" value={value.image_url||""} onChange={e=>onChange({...value,image_url:e.target.value})}/>
      </div>
      <Field label="Description courte" value={value.short_description||""} onChange={v=>onChange({...value,short_description:v})} required={false}/>
      <div><Label>Description</Label><Textarea className="mt-2 bg-surface" value={value.description||""} onChange={e=>onChange({...value,description:e.target.value})}/></div>
      <Field label="Highlights (séparés par |)" value={value.highlights.join(" | ")} onChange={v=>onChange({...value,highlights:v.split("|").map((x:string)=>x.trim()).filter(Boolean)})} required={false}/>
      <div className="grid gap-2 sm:grid-cols-2">
        <label className="flex gap-2 text-sm"><input type="checkbox" checked={value.featured} onChange={e=>onChange({...value,featured:e.target.checked})}/> Produit vedette</label>
        <label className="flex gap-2 text-sm"><input type="checkbox" checked={value.visible} onChange={e=>onChange({...value,visible:e.target.checked})}/> Visible sur le site</label>
      </div>
      <div className="flex gap-2">
        <Button type="submit" disabled={uploading}><Save className="mr-2 h-4 w-4"/>Enregistrer</Button>
        {value.id ? <Button type="button" variant="outline" onClick={onCancel}>Annuler</Button> : null}
      </div>
    </form>
  );
}

function CategoryForm({value,categories,onChange,onSubmit,onCancel}:{value:Omit<Category,"id">&{id?:string};categories?:Category[];onChange:(v:any)=>void;onSubmit:(e:React.FormEvent)=>void;onCancel:()=>void}){const [uploading,setUploading]=useState(false);const [uploadError,setUploadError]=useState("");const handleImage=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;setUploading(true);setUploadError("");try{onChange({...value,image_url:await uploadProductImage(file,"categories")});}catch(err){setUploadError(err instanceof Error?err.message:"Upload impossible");}finally{setUploading(false);e.target.value="";}};return <form onSubmit={onSubmit} className="rounded-2xl border border-border bg-card p-6 space-y-4"><h2 className="font-display text-lg font-semibold">{value.id?"Modifier":"Nouvelle"} catégorie</h2><div className="grid gap-3 sm:grid-cols-2"><Field label="Nom" value={value.name} onChange={v=>onChange({...value,name:v})}/><Field label="Slug" value={value.slug} onChange={v=>onChange({...value,slug:v})} required={false}/></div><div><Label>Catégorie parente</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.parent_id||""} onChange={e=>onChange({...value,parent_id:e.target.value||null})}><option value="">Catégorie principale</option>{(categories||[]).filter(c=>c.id!==value.id).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div><Label>Description</Label><Textarea className="mt-2 bg-surface" value={value.description||""} onChange={e=>onChange({...value,description:e.target.value})}/></div><div><Label>Image de la catégorie</Label><div className="mt-2 flex flex-col gap-3 sm:flex-row"><Input type="file" accept="image/*" onChange={handleImage} disabled={uploading} className="bg-surface"/>{value.image_url?<img src={value.image_url} alt="" className="h-20 w-20 rounded-lg border border-border object-cover"/>:null}</div>{uploading?<p className="mt-2 text-xs text-muted-foreground">Téléversement en cours…</p>:null}{uploadError?<p className="mt-2 text-xs text-destructive">{uploadError}</p>:null}<Input className="mt-3 bg-surface" placeholder="Ou collez une URL d'image existante" value={value.image_url||""} onChange={e=>onChange({...value,image_url:e.target.value})}/></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Ordre d'affichage" value={String(value.sort_order)} onChange={v=>onChange({...value,sort_order:Number(v)||0})} type="number"/><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={value.visible} onChange={e=>onChange({...value,visible:e.target.checked})}/> Visible sur le site</label></div><div className="flex gap-2"><Button type="submit" disabled={uploading}><Save className="mr-2 h-4 w-4"/>Enregistrer</Button>{value.id&&<Button type="button" variant="outline" onClick={onCancel}>Annuler</Button>}</div></form>}

function PromotionForm({value,categories,products,onChange,onSubmit,onCancel}:{value:Promotion;categories:Category[];products:Product[];onChange:(v:Promotion)=>void;onSubmit:(e:React.FormEvent)=>void;onCancel:()=>void}){return <form onSubmit={onSubmit} className="rounded-2xl border border-border bg-card p-6 space-y-4"><h2 className="font-display text-lg font-semibold">{value.id?"Modifier":"Nouvelle"} promotion</h2><Field label="Nom de la promotion" value={value.name} onChange={v=>onChange({...value,name:v})}/><div><Label>Description</Label><Textarea className="mt-2 bg-surface" value={value.description||""} onChange={e=>onChange({...value,description:e.target.value})}/></div><div className="grid gap-3 sm:grid-cols-2"><div><Label>Type de remise</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.discount_type} onChange={e=>onChange({...value,discount_type:e.target.value as "percent"|"fixed"})}><option value="percent">Pourcentage</option><option value="fixed">Montant fixe</option></select></div><Field label="Valeur" value={String(value.discount_value)} onChange={v=>onChange({...value,discount_value:Number(v)||0})} type="number"/></div><div><Label>Portée</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.scope_type} onChange={e=>onChange({...value,scope_type:e.target.value as Promotion["scope_type"],scope_id:null})}><option value="all">Toute la boutique</option><option value="category">Une catégorie</option><option value="product">Un produit</option></select></div>{value.scope_type==="category"&&<select className="h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.scope_id||""} onChange={e=>onChange({...value,scope_id:e.target.value||null})}><option value="">Choisir une catégorie</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>}{value.scope_type==="product"&&<select className="h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={value.scope_id||""} onChange={e=>onChange({...value,scope_id:e.target.value||null})}><option value="">Choisir un produit</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select>}<div className="grid gap-3 sm:grid-cols-2"><Field label="Début" value={value.starts_at?value.starts_at.slice(0,16):""} onChange={v=>onChange({...value,starts_at:v?new Date(v).toISOString():null})} type="datetime-local" required={false}/><Field label="Fin" value={value.ends_at?value.ends_at.slice(0,16):""} onChange={v=>onChange({...value,ends_at:v?new Date(v).toISOString():null})} type="datetime-local" required={false}/></div><label className="flex gap-2 text-sm"><input type="checkbox" checked={value.active} onChange={e=>onChange({...value,active:e.target.checked})}/> Promotion active</label><div className="flex gap-2"><Button type="submit"><Save className="mr-2 h-4 w-4"/>Enregistrer</Button>{value.id&&<Button type="button" variant="outline" onClick={onCancel}>Annuler</Button>}</div></form>}
function ScreenPricesPanel({screenPrices,search,setSearch,onSave}:{screenPrices:ScreenPrice[];search:string;setSearch:(v:string)=>void;onSave:(row:{id?:string;brand:string;model:string;available:boolean;screen_price:number;installation_price:number;notes:string|null})=>Promise<void>}){const rows=PHONE_BRANDS.flatMap(brand=>(PHONE_CATALOG[brand]||[]).map(model=>({brand,model})));const filtered=rows.filter(x=>(x.brand+" "+x.model).toLowerCase().includes(search.toLowerCase()));return <section className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><h2 className="font-display text-lg font-semibold">Tarifs des écrans</h2><p className="mt-1 text-xs text-muted-foreground">Gérez la disponibilité, le prix de l’écran et le prix de pose. Les mêmes tarifs sont affichés au client.</p><Input className="mt-4 bg-surface" placeholder="Rechercher une marque ou un modèle…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="divide-y divide-border">{filtered.map(x=>{const saved=screenPrices.find(s=>s.brand===x.brand&&s.model===x.model);return <ScreenPriceRow key={x.brand+"|"+x.model} brand={x.brand} model={x.model} saved={saved} onSave={onSave}/>})}{filtered.length===0&&<p className="p-6 text-sm text-muted-foreground">Aucun modèle trouvé.</p>}</div></section>}

function ScreenPriceRow({brand,model,saved,onSave}:{brand:string;model:string;saved?:ScreenPrice;onSave:(row:{id?:string;brand:string;model:string;available:boolean;screen_price:number;installation_price:number;notes:string|null})=>Promise<void>}){const [available,setAvailable]=useState(saved?.available??false);const [screenPrice,setScreenPrice]=useState(String(saved?.screen_price??0));const [installationPrice,setInstallationPrice]=useState(String(saved?.installation_price??0));const [notes,setNotes]=useState(saved?.notes??"");const [busy,setBusy]=useState(false);useEffect(()=>{setAvailable(saved?.available??false);setScreenPrice(String(saved?.screen_price??0));setInstallationPrice(String(saved?.installation_price??0));setNotes(saved?.notes??"")},[saved?.id,saved?.updated_at]);const save=async()=>{setBusy(true);try{await onSave({id:saved?.id,brand,model,available,screen_price:Number(screenPrice)||0,installation_price:Number(installationPrice)||0,notes});}finally{setBusy(false)}};return <div className="grid gap-3 p-4 lg:grid-cols-[1.4fr_1.8fr_1fr_1fr_auto] lg:items-end"><div><p className="text-sm font-semibold">{brand}</p><p className="text-xs text-muted-foreground">{model}</p></div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={available} onChange={e=>setAvailable(e.target.checked)}/><span>{available?"Disponible":"Non disponible"}</span></label><Field label="Écran (MAD)" value={screenPrice} onChange={setScreenPrice} type="number"/><Field label="Pose (MAD)" value={installationPrice} onChange={setInstallationPrice} type="number"/><Button type="button" onClick={()=>void save()} disabled={busy}>{busy?"…":"Enregistrer"}</Button><div className="lg:col-span-5"><Input className="bg-surface" placeholder="Note (optionnel)" value={notes} onChange={e=>setNotes(e.target.value)}/></div></div>}

function RepairForm({value,onChange,onSubmit,onCancel}:{value:Omit<Repair,"id">&{id?:string};onChange:(v:any)=>void;onSubmit:(e:React.FormEvent)=>void;onCancel:()=>void}){const models=value.device_brand==="Tous"?[]:(PHONE_CATALOG[value.device_brand]||[]);const selectedBrand=value.device_brand==="Tous"?"Tous":(PHONE_BRANDS.includes(value.device_brand)?value.device_brand:"");const selectedModel=value.device_brand==="Tous"?"Tous":(models.includes(value.device_model)?value.device_model:"");return <form onSubmit={onSubmit} className="rounded-2xl border border-border bg-card p-6 space-y-4"><h2 className="font-display text-lg font-semibold">{value.id?"Modifier":"Nouveau"} service</h2><div className="grid gap-3 sm:grid-cols-2"><div><Label>Marque</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={selectedBrand} onChange={e=>{const brand=e.target.value;onChange({...value,device_brand:brand||"Tous",device_model:"Tous"});}}><option value="">Sélectionner une marque</option><option value="Tous">Tous</option>{PHONE_BRANDS.map(brand=><option key={brand} value={brand}>{brand}</option>)}</select></div><div><Label>Modèle</Label><select className="mt-2 h-10 w-full rounded-md border border-border bg-surface px-3 text-sm" value={selectedModel} disabled={!selectedBrand||selectedBrand==="Tous"} onChange={e=>onChange({...value,device_model:e.target.value||"Tous"})}><option value="Tous">Tous les modèles</option>{models.map(model=><option key={model} value={model}>{model}</option>)}</select></div></div><Field label="Nom du service" value={value.service_name} onChange={v=>onChange({...value,service_name:v})}/><Field label="Slug" value={value.slug||""} onChange={v=>onChange({...value,slug:v})} required={false}/><div><Label>Description</Label><Textarea className="mt-2 bg-surface" value={value.description||""} onChange={e=>onChange({...value,description:e.target.value})}/></div><div className="grid grid-cols-2 gap-3"><Field label="Prix à partir de" value={String(value.estimated_price)} onChange={v=>onChange({...value,estimated_price:Number(v)||0})} type="number"/><Field label="Durée" value={value.repair_time||""} onChange={v=>onChange({...value,repair_time:v})}/></div><label className="flex gap-2 text-sm"><input type="checkbox" checked={Boolean(value.available)} onChange={e=>onChange({...value,available:e.target.checked})}/> Disponible</label><div className="flex gap-2"><Button type="submit"><Save className="mr-2 h-4 w-4"/>Enregistrer</Button>{value.id&&<Button type="button" variant="outline" onClick={onCancel}>Annuler</Button>}</div></form>}
function Field({label,value,onChange,type="text",required=true}:{label:string;value:string;onChange:(v:string)=>void;type?:string;required?:boolean}){return <div><Label>{label}</Label><Input className="mt-2 bg-surface" type={type} min={type==="number"?0:undefined} step={type==="number"?1:undefined} value={value} onChange={e=>onChange(e.target.value)} required={required}/></div>}
function Shell({children}:{children:React.ReactNode}){return <div className="min-h-screen bg-background px-3 py-5 sm:px-6 sm:py-8 lg:px-8"><div className="mx-auto max-w-7xl">{children}</div></div>}
function Panel({children}:{children:React.ReactNode}){return <div className="mx-auto max-w-xl rounded-2xl border border-gold/30 bg-card p-8">{children}</div>}

